#[test]fn actual_partial_input_is_typed_and_cannot_enter_full_policy_or_checker_role_even_with_same_bytes(){
 let root=scratch::dir("handler-typed-partial-input");std::fs::create_dir_all(root.join("code")).unwrap();std::fs::write(root.join("deepquarry.dme"),"#include \"code/probe.dm\"\n").unwrap();std::fs::write(root.join("code/probe.dm"),"/datum/probe\n    proc/p()\n        return\n").unwrap();
 let provider=Provider::new();let host=original_host::Host::new();let settings=host.clone()as Arc<dyn SettingExpressionQueries>;let seed=dm_tree::checker_builtins::original_analysis_seed().unwrap();let executor=dm_exec::BuildExecutor::new(1).unwrap();let config=dm_tree::frontend::FrontendConfig{workers:1,engine:Some(seed.frontend_seed()),observer:None};let path=root.join("deepquarry.dme");
 let first=dm_tree::frontend::build_for_original_handlers_structural_checked(&path,&provider,config,None,&executor,&settings).unwrap();let second=dm_tree::frontend::build_for_original_handlers_structural_checked(&path,&provider,config,None,&executor,&settings).unwrap();let first_source=first.handlers_structural_source().unwrap();let second_source=second.handlers_structural_source().unwrap();let input=dm_analysis::policy_inputs::HandlersStructuralInputs::capture(&first_source).unwrap();
 assert!(input.matches(&first_source));assert!(!input.matches(&second_source),"equal source revision or bytes cannot replace the exact partial owner");assert_eq!(input.preparation_purpose(),dm_tree::frontend::DiagnosticPreparationPurpose::OriginalHandlersStructuralComplete);assert!(dm_analysis::policy_inputs::PolicyInputs::capture_diagnostic(first_source.view(),[]).is_err(),"full PolicyInputs must not accept the structural DiagnosticSourceView escape");assert!(first.checker_source_view().is_err());assert!(first.original_analysis_completeness().is_none());
 let full=dm_tree::frontend::build_for_original_analysis_with_state_checked(&path,&provider,&Default::default(),config,None,&executor,None,&settings).unwrap();assert!(full.handlers_structural_source().is_err());assert!(dm_analysis::policy_inputs::PolicyInputs::capture_diagnostic(&full.source_view().unwrap(),[]).is_ok());assert_eq!(first_source.view().expanded_text(),full.source_view().unwrap().expanded_text(),"the negative control deliberately uses the same stream bytes");
}

